const p=$json.body;
const exact=['schemaVersion','requestId','projectId','revision','action','brief','messages'];
if(p?.pricing!==undefined)exact.push('pricing');
if(p?.pricing!==undefined && (Object.keys(p.pricing).sort().join('|')!==['currency','creationCents','monthlyCents','extraPageCents'].sort().join('|') || p.pricing.currency!=='EUR' || ['creationCents','monthlyCents','extraPageCents'].some(k=>!Number.isSafeInteger(p.pricing[k])||p.pricing[k]<0)))throw Error('PORTAL_PRICING_INVALID');
if(!p||Object.keys(p).sort().join('|')!==exact.sort().join('|')||p.schemaVersion!==1||!['message','generate_preview'].includes(p.action)||!Number.isSafeInteger(p.revision)||p.revision<2)throw Error('PORTAL_CONTRACT_INVALID');
for(const k of ['requestId','projectId'])if(!/^[a-f0-9-]{36}$/.test(p[k]))throw Error('PORTAL_BINDING_INVALID');
if(!p.brief||!Array.isArray(p.brief.pages)||!p.brief.businessName||!p.brief.description||!p.brief.audience||!Array.isArray(p.messages)||p.messages.length>20||p.messages.some(m=>!['user','assistant'].includes(m.role)||typeof m.text!=='string'||m.text.length>8000)||JSON.stringify(p).length>100000)throw Error('PORTAL_CONTEXT_INVALID');
return [{json:p}];

const p=$('Valider le contexte du site').first().json;
const r=$input.first().json;
if(r.status!=='completed'||!Array.isArray(r.output))throw Error('MODEL_INCOMPLETE');
const messages=r.output.filter(x=>x.type==='message');
if(messages.length!==1||!Array.isArray(messages[0].content)||messages[0].content.length!==1||messages[0].content[0].type!=='output_text')throw Error('MODEL_OUTPUT_INVALID');
const raw=messages[0].content[0].text;
const v=typeof raw==='string'?JSON.parse(raw):raw;
if(!v||Object.keys(v).sort().join('|')!=='html|reply'||typeof v.reply!=='string'||v.reply.length<3||v.reply.length>8000||typeof v.html!=='string'||v.html.length>150000)throw Error('MODEL_SCHEMA_INVALID');
if(p.action==='message'&&v.html!=='')throw Error('UNREQUESTED_PREVIEW');
if(p.action==='generate_preview'&&(v.html.length<300||!/<html\b/i.test(v.html)||!/<\/html\s*>/i.test(v.html)||/<\s*(script|iframe|object|embed|base|form)\b|\bon\w+\s*=|javascript:/i.test(v.html)))throw Error('ARTIFACT_INVALID');
return [{json:{schemaVersion:1,requestId:p.requestId,projectId:p.projectId,revision:p.revision,reply:v.reply,html:v.html}}];
